    // const LC4P_Jacobian = (P, x) => {let derivation_dy1_dP1 = (1 / (1 + ((x / P[1]) ** P[2]))); let derivation_dy1_dP2 = (((P[0] - P[3]) * P[2] * (( x / P[1]) ** P[2])) / (P[1] * ((1 + ((x / P[1]) ** P[2])) ** 2))); let derivation_dy1_dP3 = (((P[3] - P[0]) * (( x / P[1]) ** P[2]) * math.log(x / P[1])) / ((1 + ((x / P[1]) ** P[2])) ** 2)); let derivation_dy1_dP4 = (1 - (1 / (1 + ((x / P[1]) ** P[2])))); return [derivation_dy1_dP1, derivation_dy1_dP2, derivation_dy1_dP3, derivation_dy1_dP4];};  // 邏輯四參數模型（4-parameter logistic model）方程的雅可比矩陣（Jacobian matrix）;
    static LC4P_Jacobian = function (P, x) { let derivation_dy1_dP1 = (1 / (1 + ((x / P[1]) ** P[2]))); let derivation_dy1_dP2 = (((P[0] - P[3]) * P[2] * (( x / P[1]) ** P[2])) / (P[1] * ((1 + ((x / P[1]) ** P[2])) ** 2))); let derivation_dy1_dP3 = (((P[3] - P[0]) * (( x / P[1]) ** P[2]) * math.log(x / P[1])) / ((1 + ((x / P[1]) ** P[2])) ** 2)); let derivation_dy1_dP4 = (1 - (1 / (1 + ((x / P[1]) ** P[2])))); return [derivation_dy1_dP1, derivation_dy1_dP2, derivation_dy1_dP3, derivation_dy1_dP4]; };

    // 自定義的邏輯五參數模型（5-parameter logistic model）方程;
    // function fit_model([P1, P2, P3, P4, P5], x) {
    //     y = P4 - (P4 - P1)/((1.0 + (x/P2)**P3)**P5);  // 邏輯五參數模型（5-parameter logistic model）方程;
    //     return y;
    // };
    // const LC5P_model = (P, x) => {let y = fit_model([P[0], P[1], P[2], P[3], P[4]], x); return y;};
    // const LC5P_model = (P, x) => {let y = (P[3] - (P[3] - P[0])/((1.0 + (x/P[1])**P[2])**P[4])); return y;};  // 邏輯五參數模型（5-parameter logistic model）方程;
    static LC5P_model = function (P, x) { let y = (P[3] - (P[3] - P[0])/((1.0 + (x/P[1])**P[2])**P[4])); return y; };
    // 必須將自變量作爲第一個參數，將待估參數作爲單獨的數組參數;
    // 應變量 y 為反應度光强度（relative light unit,RLU）;
    // 自變量 x 為含量劑量濃度（Dosage Concentration）;
    // 參數 P1 為 –∞ ≈ 0 劑量時的反應度相對光子數，是模型方程曲綫負向最小值漸近綫;
    // 參數 P2 為反應度相對光子數的最大值與最小值之差的一半時的含量劑量濃度值，即 y = ( ymax – ymin ) ÷ 2 對應的 x 值;
    // 參數 P3 為模型方程曲綫的斜率;
    // 參數 P4 為 +∞ 劑量時的反應度相對光子數，是模型方程曲綫正向最大值漸近綫;
    // 參數 P5 為不對稱因子，當參數 P5 = 1 時，函數曲綫是圍繞拐點的對稱圖形，5 參數模型退化等效於 4 參數模型;

    // The finite difference method is used above to approximate the Jacobian.
