    //     let derivation_dy1_dP2 = (((P1 - P4) * P5 * P3 * (( x / P2) ** P3)) / (((1 + (( x / P2) ** P3)) ** P5) * (1 + ((x / P2) ** P3)) * P2));
    //     // Jacobian_y1_p3 = partial derivation (∂y1/∂P3);
    //     let derivation_dy1_dP3 = (((P4 - P1) * P5 * (( x / P2) ** P3) * math.log(x / P2)) / (((1 + (( x / P2) ** P3)) ** P5) * (1 + (( x / P2) ** P3))));
    //     // Jacobian_y1_p4 = partial derivation (∂y1/∂P4);
