// 數值分析方法求解方程根近似值;
function Roots_Equation (
    Y_target,
    f,
    df,
    X_0,
    tolerance = 1e-6,
    maxIter = 200,
    method = "Bisection"
) {

    // 牛頓迭代法（斜截法）求解方程根近似值;
    function Roots_Newton_Raphson (f, df, X_0, tolerance = 1e-6, maxIter = 100) {
        let x = X_0;
        let delta = 0;
        for (let i = 0; i < maxIter; i++) {
            delta = f(x) / df(x);
            x = x - delta;
            // 判斷根收斂;
            if (math.abs(delta) < tolerance) {
                break;
            };
        };
        delta = null;
        // 迭代結果如未收則返回迭代最後一個值;
        return x;
    };

    // 二分法求解方程根近似值;
    function Roots_Bisection (f, X_y0down, X_y0up, tolerance = 1e-6, maxIter = 300) {
        if (f(X_y0down) * f(X_y0up) >= 0) {
            return "Error, must be : [ f(X_y0down) × f(X_y0up) < 0 ].";
        };
        let x = X_y0up;
        for (let i = 0; i < maxIter; i++) {
            x = (X_y0down + X_y0up) / 2;
            // 判斷根收斂;
            if (math.abs(f(x)) < tolerance) {
                break;
            };
            // 根據初值符號判斷根所在區間範圍;
            if (f(X_y0down) * f(x) < 0) {
                X_y0up = x;  // 判斷根在 [X_y0down, x] 區間;
            } else {
                X_y0down = x;  // 判斷根在 [x, X_y0up] 區間;
            };
            // 判斷根收斂;
            if (math.abs((X_y0up - X_y0down) / 2) < tolerance) {
                break;
            };
        };
        // 迭代結果如未收則返回迭代最後一個值;
        return x;
    };

    // 割綫法求解方程根近似值;
    function Roots_Secant (f, X_1, X_2, tolerance = 1e-6, maxIter = 200) {
        let x = X_2;
        for (let i = 0; i < maxIter; i++) {
            // 判斷分母是否爲接近零（0）值，若接近零（0）值則中止迭代;
            // if (math.abs(f(X_2) - f(X_1)) < tolerance) {
            if (math.abs(f(X_2) - f(X_1)) < 1e-12) {
                break;
            };
            // 割綫法求根迭代公式;
            x = X_2 - f(X_2) * (X_2 - X_1) / (f(X_2) - f(X_1));
            // 判斷根收斂;
            if (math.abs(x - X_2) < tolerance) {
                break;
            };
            X_1 = X_2;
            X_2 = x;
        };
        // 迭代結果如未收則返回迭代最後一個值;
        return x;
    };

    let X_target = NaN;
    if ((Object.prototype.toString.call(Y_target).toLowerCase() === '[object number]') || ((Y_target === (+Infinity)) || (Y_target === (-Infinity)))) {
        const f_0 = (x) => { let y_0 = (f(x) - Y_target); return y_0; };
        if (method === "Newton_Raphson") {
            X_target = Roots_Newton_Raphson(f_0, df, X_0, tolerance, maxIter);
        } else if (method === "Secant") {
            X_target = Roots_Secant(f_0, df, X_0, tolerance, maxIter);
        } else if (method === "Bisection") {
            X_target = Roots_Bisection(f_0, df, X_0, tolerance, maxIter);
        } else {
            X_target = NaN;
        };
    } else if (Object.prototype.toString.call(Y_target).toLowerCase() === '[object string]') {
        if ((Y_target === "+Base.Inf") || (Y_target === "+Inf") || (Y_target === "+inf") || (Y_target === "+Infinity") || (Y_target === "+infinity") || (Y_target === "Base.Inf") || (Y_target === "Inf") || (Y_target === "inf") || (Y_target === "Infinity") || (Y_target === "infinity")) {
            const f_0 = (x) => { let y_0 = (f(x) - (+Infinity)); return y_0; };
            if (method === "Newton_Raphson") {
                X_target = Roots_Newton_Raphson(f_0, df, X_0, tolerance, maxIter);
            } else if (method === "Secant") {
                X_target = Roots_Secant(f_0, df, X_0, tolerance, maxIter);
            } else if (method === "Bisection") {
                X_target = Roots_Bisection(f_0, df, X_0, tolerance, maxIter);
            } else {
                X_target = NaN;
            };
        } else if ((Y_target === "-Base.Inf") || (Y_target === "-Inf") || (Y_target === "-inf") || (Y_target === "-Infinity") || (Y_target === "-infinity")) {
            const f_0 = (x) => { let y_0 = (f(x) - (-Infinity)); return y_0; };
            if (method === "Newton_Raphson") {
                X_target = Roots_Newton_Raphson(f_0, df, X_0, tolerance, maxIter);
            } else if (method === "Secant") {
                X_target = Roots_Secant(f_0, df, X_0, tolerance, maxIter);
            } else if (method === "Bisection") {
                X_target = Roots_Bisection(f_0, df, X_0, tolerance, maxIter);
            } else {
                X_target = NaN;
            };
        } else {
            X_target = NaN;
        };
    } else if ((Object.prototype.toString.call(Y_target).toLowerCase() === '[object array]') && (Y_target.length > 0)) {
        X_target = new Array;
        // X_target = new Array(parseInt(Y_target.length)).fill(NaN);
        for (let j = 0; j < Y_target.length; j++) {
            let X_target_i = NaN;
            if ((Object.prototype.toString.call(Y_target[j]).toLowerCase() === '[object number]') || ((Y_target[j] === (+Infinity)) || (Y_target[j] === (-Infinity)))) {
                const f_0 = (x) => { let y_0 = (f(x) - Y_target[j]); return y_0; };
                if (method === "Newton_Raphson") {
                    X_target_i = Roots_Newton_Raphson(f_0, df, X_0, tolerance, maxIter);
                } else if (method === "Secant") {
                    X_target_i = Roots_Secant(f_0, df, X_0, tolerance, maxIter);
                } else if (method === "Bisection") {
                    X_target_i = Roots_Bisection(f_0, df, X_0, tolerance, maxIter);
                } else {
                    X_target_i = NaN;
                };
            } else if (Object.prototype.toString.call(Y_target[j]).toLowerCase() === '[object string]') {
                if ((Y_target[j] === "+Base.Inf") || (Y_target[j] === "+Inf") || (Y_target[j] === "+inf") || (Y_target[j] === "+Infinity") || (Y_target[j] === "+infinity") || (Y_target[j] === "Base.Inf") || (Y_target[j] === "Inf") || (Y_target[j] === "inf") || (Y_target[j] === "Infinity") || (Y_target[j] === "infinity")) {
                    const f_0 = (x) => { let y_0 = (f(x) - (+Infinity)); return y_0; };
                    if (method === "Newton_Raphson") {
                        X_target_i = Roots_Newton_Raphson(f_0, df, X_0, tolerance, maxIter);
                    } else if (method === "Secant") {
                        X_target_i = Roots_Secant(f_0, df, X_0, tolerance, maxIter);
                    } else if (method === "Bisection") {
                        X_target_i = Roots_Bisection(f_0, df, X_0, tolerance, maxIter);
                    } else {
                        X_target_i = NaN;
                    };
                } else if ((Y_target[j] === "-Base.Inf") || (Y_target[j] === "-Inf") || (Y_target[j] === "-inf") || (Y_target[j] === "-Infinity") || (Y_target[j] === "-infinity")) {
                    const f_0 = (x) => { let y_0 = (f(x) - (-Infinity)); return y_0; };
                    if (method === "Newton_Raphson") {
                        X_target_i = Roots_Newton_Raphson(f_0, df, X_0, tolerance, maxIter);
                    } else if (method === "Secant") {
                        X_target_i = Roots_Secant(f_0, df, X_0, tolerance, maxIter);
                    } else if (method === "Bisection") {
                        X_target_i = Roots_Bisection(f_0, df, X_0, tolerance, maxIter);
                    } else {
                        X_target_i = NaN;
                    };
                } else {
                    X_target_i = NaN;
                };
            } else {
                X_target_i = NaN;
            };
            X_target.push(X_target_i);
            // X_target[j] = X_target_i;
            X_target_i = null;
        };
    } else {
        X_target = NaN;
    };

    return X_target;
};
module.exports.RootsEquation = Roots_Equation;


