                    yvUpper = parseFloat(parseFloat(Yvals[i]) + parseFloat(math.sqrt(parseFloat(parseFloat(parseFloat(yvsd) - parseFloat(Yvals[i])) ** parseInt(2)) + parseFloat(parseFloat(YdataSTD[i]) ** parseInt(2)))));
