    // 邏輯五參數模型（4-parameter logistic model）方程求解雅可比矩陣（Jacobian matrix）函數（Function）;
    // if ((typeof (jacobianFunction) === undefined) || (jacobianFunction === undefined)) {
    //     let jacobianFunction = null;
