            const LC4P_Jacobian = function (P) { return function (x) { let derivation_dy1_dP1 = (1 / (1 + ((x / P[1]) ** P[2]))); let derivation_dy1_dP2 = (((P[0] - P[3]) * P[2] * (( x / P[1]) ** P[2])) / (P[1] * ((1 + ((x / P[1]) ** P[2])) ** 2))); let derivation_dy1_dP3 = (((P[3] - P[0]) * (( x / P[1]) ** P[2]) * math.log(x / P[1])) / ((1 + ((x / P[1]) ** P[2])) ** 2)); let derivation_dy1_dP4 = (1 - (1 / (1 + ((x / P[1]) ** P[2])))); return [derivation_dy1_dP1, derivation_dy1_dP2, derivation_dy1_dP3, derivation_dy1_dP4]; }; };

            jacobianFunction = LC4P_Jacobian;
