        "errorTolerance": errorTolerance,  // 10e-3, Stop as soon as the error drops below this value;
        "improvementThreshold": improvementThreshold,  // 1e-3, Threshold defining what counts as an improvement;
        "timeout": timeout,  // 60, // undefined, Maximum running time in seconds; throws when exceeded;
        "dampingStepDown": dampingStepDown,  // 9, Factor used to reduce the damping when an update improves the fit;
